<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;class StoreAttendanceEventRequest extends FormRequest{public function authorize(){return$this->user()?->can('asistencia.crear')??false;}public function rules(){return['attendance_opens_at'=>'required|date','attendance_closes_at'=>'required|date|after:attendance_opens_at','ends_at'=>'required|date|after:attendance_opens_at','requires_signature'=>'nullable|boolean','allows_external_attendees'=>'nullable|boolean'];}public function messages(){return['attendance_closes_at.after'=>'El cierre de asistencia debe ser posterior a la apertura.','ends_at.after'=>'La finalización debe ser posterior a la apertura.'];}}
